PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT ?subject ?object ?subjectLabel ?objectLabel ?subjectType ?subjectSitelinks ?objectSitelinks WHERE {
  {
    SELECT ?subject ?object WHERE {
      ?subject wdt:P9001 ?object .
    }
    LIMIT 10 OFFSET 0
  }
  OPTIONAL { ?subject wdt:P31 ?subjectType . }
  OPTIONAL { ?subject wikibase:sitelinks ?subjectSitelinks . }
  OPTIONAL { ?object wikibase:sitelinks ?objectSitelinks . }
  ?subject rdfs:label ?subjectLabel .
  FILTER(LANG(?subjectLabel) = "en")
  ?object rdfs:label ?objectLabel .
  FILTER(LANG(?objectLabel) = "en")
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT ?property ?ancestor WHERE {
  ?property wikibase:propertyType wikibase:WikibaseItem .
  ?property wdt:P1647+ ?ancestor .
}

